import dns from "node:dns/promises"; import ipaddr from "ipaddr.js";
function blocked(address:string){try{const a=ipaddr.parse(address); if(a.kind()==="ipv6"&&a.isIPv4MappedAddress())return blocked(a.toIPv4Address().toString()); return a.range()!=="unicast";}catch{return true;}}
export async function assertSafeUrl(value:string){const u=new URL(value);if(!["http:","https:"].includes(u.protocol)||u.username||u.password||!["","80","443"].includes(u.port))throw new Error("That destination is not allowed.");if(u.hostname==="localhost"||u.hostname.endsWith(".local"))throw new Error("Private destinations are not allowed.");const addresses=await dns.lookup(u.hostname,{all:true});if(!addresses.length||addresses.some(x=>blocked(x.address)))throw new Error("Private or reserved destinations are not allowed.");return u;}
export async function safeFetch(value:string, limit=2*1024*1024){let url=value;for(let hop=0;hop<6;hop++){await assertSafeUrl(url);const response=await fetch(url,{redirect:"manual",signal:AbortSignal.timeout(10000),headers:{Accept:"text/html,application/xhtml+xml;q=0.9,*/*;q=0.1","User-Agent":"KeepsakeBookmarkManager/1.0"}});if(response.status>=300&&response.status<400&&response.headers.get("location")){if(hop===5)throw new Error("Too many redirects.");url=new URL(response.headers.get("location")!,url).toString();continue;}const type=response.headers.get("content-type")??"";if(!type.includes("text/html")&&!type.includes("application/xhtml+xml"))throw new Error("The destination did not return a web page.");const reader=response.body?.getReader();let size=0;const chunks:Uint8Array[]=[];if(reader){while(true){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>limit){await reader.cancel();throw new Error("The page is too large to preview.");}chunks.push(value);}}return {url,response,body:new TextDecoder().decode(Buffer.concat(chunks))};}throw new Error("Could not retrieve this page.");}

