40	  const or = (): SearchNode => { const nodes = [and()]; while (tokens[at]?.value.toUpperCase() === "OR") { const p = tokens[at++].pos; if (!tokens[at]) throw new SearchSyntaxError("Dangling OR", p, source.length, "Add another condition."); nodes.push(and()); } return nodes.length === 1 ? nodes[0] : { type: "or", children: nodes }; };
41	  const result = or(); if (at !== tokens.length) throw new SearchSyntaxError("Unexpected search input", tokens[at].pos, tokens[at].pos + tokens[at].value.length, "Review this part of the query."); return result;
42	}
43	export function describeSearch(node: SearchNode | null): string[] {
44	  if (!node) return [];
45	  if (node.type === "and" || node.type === "or") return [`${node.type.toUpperCase()} group`, ...node.children.flatMap(describeSearch)];
46	  if (node.type === "not") return describeSearch(node.child).map(x => `NOT ${x}`);
47	  return [`${node.type}: ${node.value}`];
48	}

