import{beforeAll,describe,it,expect}from"vitest";import fs from"node:fs";import path from"node:path";import os from"node:os";
const temp=path.join(os.tmpdir(),`keepsake-${process.pid}-${Date.now()}.db`);process.env.DATABASE_PATH=temp;
let service:typeof import("@/server/services/bookmark-service");let io:typeof import("@/server/services/import-export");let prefs:typeof import("@/server/services/preferences");let saved:typeof import("@/server/services/saved-search-service");let bulk:typeof import("@/server/services/bulk");
beforeAll(async()=>{service=await import("@/server/services/bookmark-service");io=await import("@/server/services/import-export");prefs=await import("@/server/services/preferences");saved=await import("@/server/services/saved-search-service");bulk=await import("@/server/services/bulk");});
describe("durable workflows",()=>{it("creates one canonical bookmark and preserves states",()=>{const a=service.createBookmark({url:"https://EXAMPLE.com:443/#x",title:"First",tags:["Reading"]});expect(a.bookmark?.isRead).toBe(false);const d=service.createBookmark({url:"https://example.com",title:"Duplicate"});expect(d.duplicate?.id).toBe(a.bookmark?.id);service.updateBookmark(a.bookmark!.id,{isRead:true,archived:true});expect(service.getBookmark(a.bookmark!.id)?.archivedAt).toBeTruthy();service.updateBookmark(a.bookmark!.id,{archived:false});expect(service.getBookmark(a.bookmark!.id)?.isRead).toBe(true);});it("searches fields, phrases, tags and status",()=>{service.createBookmark({url:"https://example.org/design",title:"Quiet Interface",description:"Useful pattern",tags:["Design"]});expect(service.listBookmarks({q:'tag:design "useful pattern"',scope:"active",read:"all",sort:"newest"}).total).toBe(1);expect(()=>service.listBookmarks({q:'"broken',scope:"active",read:"all",sort:"newest"})).toThrow();});it("imports folders, skips duplicates and exports escaped HTML",()=>{const result=io.importHtml('<!DOCTYPE NETSCAPE-Bookmark-file-1><DL><DT><H3>Research</H3><DL><DT><A HREF="https://import.test/a">A &amp; B</A></DL></DL>');expect(result.added).toBe(1);expect(service.findByUrl("https://import.test/a")?.tags).toContain("Research");expect(io.importHtml('<DL><DT><A HREF="https://import.test/a">Again</A></DL>').duplicates).toBe(1);const html=io.exportHtml();expect(html).toContain("NETSCAPE-Bookmark-file-1");expect(html).toContain("A &amp; B");});it("persists preferences and live saved searches",()=>{expect(prefs.getPreferences().pageSize).toBe(25);prefs.setPreferences({defaultSort:"title_asc",pageSize:50,textSize:"large"});expect(prefs.getPreferences().textSize).toBe("large");const id=saved.saveSearch({name:"Design",queryText:"tag:design",scope:"active",readFilter:"all",sortKey:"newest"});expect(saved.listSaved()).toHaveLength(1);saved.deleteSearch(id);});it("previews and executes exact bulk targets",()=>{const ids=service.listBookmarks({q:"",scope:"active",read:"all",sort:"newest"},1,100).items.map(x=>x.id);const p=bulk.previewBulk({ids,action:{type:"unread"}});expect(p.count).toBe(ids.length);expect(bulk.executeBulk(p.token)).toMatchObject({changed:ids.length});});});
afterAll(()=>{for(const suffix of["","-wal","-shm"])try{fs.unlinkSync(temp+suffix)}catch{}});

